import type React from "react";
import { forwardRef, useId } from "react";

const NurseJoy = forwardRef<SVGSVGElement, React.HTMLProps<SVGSVGElement>>(
  (props, ref) => {
    const id = useId();
    const patternId = `pattern-${id}`;
    const imageId = `image-${id}`;
    return (
      <svg
        aria-hidden="true"
        width="57"
        height="68"
        viewBox="0 0 57 68"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        xmlnsXlink="http://www.w3.org/1999/xlink"
        {...props}
        ref={ref}
      >
        <rect width="57" height="68" fill={`url(#${patternId})`} />
        <defs>
          <pattern
            id={patternId}
            patternContentUnits="objectBoundingBox"
            width="1"
            height="1"
          >
            <use
              xlinkHref={`#${imageId}`}
              transform="matrix(0.0181818 0 0 0.0151515 -2.58182 -0.0909091)"
            />
          </pattern>
          <image
            id={imageId}
            width="272"
            height="288"
            preserveAspectRatio="none"
            xlinkHref="data:image/png;base64,"
          />
        </defs>
      </svg>
    );
  },
);

NurseJoy.displayName = "NurseJoy";

export default NurseJoy;
